using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class NurseHairContourFit {
 const string Native="Assets/EntityStudioGenerated/RebirthNurseNative";public const string BaselinePrefix="BeforeHairContourV2_";
 static string Key(Vector3 p){return Mathf.RoundToInt(p.x*100000)+","+Mathf.RoundToInt(p.y*100000)+","+Mathf.RoundToInt(p.z*100000);}
 public static void Run(){var model=PrefabUtility.LoadPrefabContents(Native+"/RebirthNurse_Authoring.prefab");var rows=new List<string>();try{foreach(var r in model.GetComponentsInChildren<SkinnedMeshRenderer>(true).Where(x=>x.name.StartsWith("LOD"))){var target=r.sharedMesh;string path=NurseVisualOptimization.Folder+"/"+BaselinePrefix+r.name+".asset";if(!File.Exists(path))AssetDatabase.CopyAsset(AssetDatabase.GetAssetPath(target),path);var source=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(!source.uv.SequenceEqual(target.uv)||!source.triangles.SequenceEqual(target.triangles))throw new Exception("Contour baseline requires explicit regeneration for changed UV/topology");var original=source.vertices;var smooth=(Vector3[])original.Clone();var hair=new HashSet<int>(source.GetTriangles(1));var pinned=new HashSet<int>(source.GetTriangles(0));var links=hair.ToDictionary(i=>i,i=>new HashSet<int>());var hi=source.GetTriangles(1);for(int j=0;j<hi.Length;j+=3)for(int a=0;a<3;a++)for(int b=0;b<3;b++)if(a!=b)links[hi[j+a]].Add(hi[j+b]);var groups=Enumerable.Range(0,original.Length).GroupBy(i=>Key(original[i])).Select(g=>g.ToArray()).ToArray();
 for(int step=0;step<12;step++){var next=(Vector3[])smooth.Clone();foreach(var group in groups){if(group.Any(i=>!hair.Contains(i)||pinned.Contains(i)))continue;int i=group[0];var p=r.transform.TransformPoint(original[i]);if(p.y>1.66f||p.y<1.30f)continue;var neighbours=group.SelectMany(j=>links[j]).Distinct().ToArray();if(neighbours.Length<3)continue;var centre=Vector3.zero;foreach(int j in neighbours)centre+=smooth[j];centre/=neighbours.Length;var v=Vector3.Lerp(smooth[i],centre,.30f);v=original[i]+Vector3.ClampMagnitude(v-original[i],.008f);foreach(int j in group)next[j]=v;}smooth=next;}
 int moved=0;float maximum=0;for(int i=0;i<smooth.Length;i++){if(pinned.Contains(i)&&smooth[i]!=original[i])throw new Exception("Body/face geometry moved");float delta=Vector3.Distance(smooth[i],original[i]);if(delta>0.000001f)moved++;maximum=Mathf.Max(maximum,delta);}var normals=target.normals;var tangents=target.tangents;var weights=target.boneWeights;target.vertices=smooth;target.RecalculateBounds();if(!target.normals.SequenceEqual(normals)||!target.tangents.SequenceEqual(tangents)||!target.boneWeights.SequenceEqual(weights))throw new Exception("Contour changed shading or weights");EditorUtility.SetDirty(target);rows.Add(r.name+" hair-only moved vertices="+moved+" maximum local displacement="+maximum+" m; body-submesh and crown pinned; all original normals/tangents/UVs/weights/triangles retained.");}AssetDatabase.SaveAssets();File.WriteAllLines(NurseVisualOptimization.Out+"/hair-contour-fit.txt",rows.Concat(new[]{"Idempotent baseline; no card overlays or new textures. Rig/collider fields not edited. Hair tip texture coverage and hairline transition remain separate unfinished issues."}));}finally{PrefabUtility.UnloadPrefabContents(model);}}
}
